```nginx
server {
    listen 80;
    server_name example.com; # Replace with your domain

    root /var/www/html;
    index index.html index.htm;

    # Directory Traversal Prevention
    location / {
        try_files $uri $uri/ =404;
    }

    # Secure File Handling - Limit access to specific directories
    location ~ /\. {
        deny all;
    }

    location ~ admin {
        # Example: Restrict access to the admin directory
        auth_basic "Restricted Area";
        auth_basic_user_file /etc/nginx/.htpasswd;
        deny all;
    }

    # Security Headers - OWASP Top 10
    add_header X-Frame-Options "SAMEORIGIN";
    add_header X-XSS-Protection "1; mode=block";
    add_header Content-Security-Policy "default-src 'self';";
    add_header X-Content-Type-Options "nosniff";

    # Zero-Downtime Deployment - Using Nginx's dynamic modules
    # (Requires pre-configured module and deployment process - example only)
    # This section needs to be adapted to your specific deployment strategy.
    # Example:  Load module, update configuration, reload Nginx
    #  (This is a placeholder - actual implementation depends on your system)
    #  dynamic_module /path/to/your/module;
    #  include /path/to/your/reload_script.sh;
}
```

